-- -----------------------------------------------------------------------------
-- 18. TRIP SEAT INVENTORY (Granular seat availability for trips)
-- -----------------------------------------------------------------------------
INSERT INTO trip_seat_inventory (trip_id, seat_id, is_available, reserved_at, held_until, lock_version)
SELECT 
    tr.trip_id,
    st.seat_id,
    CASE WHEN MOD(tr.trip_id + st.seat_id, 3) = 0 THEN FALSE ELSE TRUE END AS is_available,
    CASE WHEN MOD(tr.trip_id + st.seat_id, 3) = 0 THEN tr.created_at ELSE NULL END AS reserved_at,
    NULL AS held_until,
    0 AS lock_version
FROM trips tr
JOIN seats st ON tr.vehicle_id = st.vehicle_id;

SET FOREIGN_KEY_CHECKS = 1;
